function activeTools(){return state.tools.filter(t=>t.toolStatus!=='Archived'&&(t.quarter||state.quarter)===state.quarter)}
function operationalTools(){return activeTools().filter(t=>t.toolStatus!=='Shipped'&&t.toolStatus!=='Archived')}
function workloadTools(){return operationalTools().filter(t=>['FI','Engineering','Powered Down','Packing'].includes(t.toolStatus))}
function priorityEligibleTools(){return workloadTools()}
function morningSortGroup(t){let c=String(t.codename||'').trim().toLowerCase();return(c==='regera'||c==='celestiq')?1:0}
function morningSortTools(list){return [...list].sort((a,b)=>{let g=morningSortGroup(a)-morningSortGroup(b);if(g)return g;return String(a.id||'').localeCompare(String(b.id||''),undefined,{numeric:true,sensitivity:'base'})})}
function nonArchivedTools(){return state.tools.filter(t=>t.toolStatus!=='Archived')}
function activeQuarters(){let q=[...new Set(nonArchivedTools().map(t=>t.quarter||state.quarter).filter(Boolean))];if(!q.includes(state.quarter))q.push(state.quarter);return q.sort()}
function toolViewQuarter(){return state.config?.toolViewQuarter||state.quarter}
function toolsForQuarter(q=toolViewQuarter()){return nonArchivedTools().filter(t=>(t.quarter||state.quarter)===q)}
function checklistIndex(t,code){return routeFor(t).findIndex(x=>x[0]===code)}
function fiProgress(t){if(!t.currentChecklist)return 0;if(t.currentChecklist===FI200)return 100;let r=routeFor(t),i=checklistIndex(t,t.currentChecklist);return i<0?0:Math.round(i/(r.length-1)*100)}
function microProgress(t){let r=routeFor(t),i=checklistIndex(t,t.microSchedule);return i<0?0:Math.round(i/(r.length-1)*100)}
function performance(t){let d=fiProgress(t)-microProgress(t);return d>5?['AHEAD','purple','ahead']:d<-5?['BEHIND','red','behind']:['ON SCHEDULE','green','on']}
/* V5.6.0 — CENTRAL AUTOMATION ENGINE
   Tool Editor / Daily Update fields are the source of truth. Everything below is derived at render time.
   The engine never overwrites historical FI, Lead/Admin, NC, Source, STR, or Shipping facts. */
function engineDaysToShip(t){if(!t.shipDate)return null;let d=dateOnly(t.shipDate),n=dateOnly(today());return Math.ceil((d-n)/86400000)}
function engineSourceIncomplete(t){return String(t.sourceRequired||'TBD').toUpperCase()==='YES'&&!['COMPLETE','COMPLETED','APPROVED','SOURCE COMPLETE'].includes(String(t.sourceStatus||'').toUpperCase())}
function engineStrIncomplete(t){return String(t.strRequired||'TBD').toUpperCase()==='YES'&&!['COMPLETE','COMPLETED','APPROVED'].includes(String(t.strStatus||'').toUpperCase())}
function deriveToolState(t){
  let brain=evaluateTool(t),perf=performance(t),days=engineDaysToShip(t),reasons=[],score=0,severity='normal';
  let escal=(t.ncs||[]).filter(n=>n.state==='Escalated'),blocking=escal.filter(n=>n.blocking);
  if(blocking.length){severity='critical';score+=1200;reasons.push(`${displayNcId(blocking[0].id)} BLOCKING ESCALATION`)}
  else if(escal.length){severity='critical';score+=1000;reasons.push(`${displayNcId(escal[0].id)} ESCALATED`)}
  if(t.toolStatus!=='Shipped'&&days!==null){
    if(days<0){severity='critical';score+=900;reasons.push(`${Math.abs(days)} DAY${Math.abs(days)===1?'':'S'} PAST SHIP DATE`)}
    else if(days<=1){if(severity!=='critical')severity='attention';score+=420;reasons.push(days===0?'SHIPS TODAY':'SHIPS TOMORROW')}
    else if(days<=5){if(severity==='normal')severity='attention';score+=260;reasons.push(`${days} DAYS TO SHIP`)}
    else if(days<=10){score+=120}
  }
  if(t.toolStatus==='FI'&&perf[0]==='BEHIND'){if(severity==='normal')severity='attention';score+=220;reasons.push('BEHIND MICRO SCHEDULE')}
  if(t.toolStatus==='Packing'&&shippingProgress(t)<100){if(severity==='normal'&&days!==null&&days<=10)severity='attention';score+=160;reasons.push(`PACKING ${shippingProgress(t)}% COMPLETE`)}
  if(engineSourceIncomplete(t)){if(severity==='normal'&&days!==null&&days<=14)severity='attention';score+=90;reasons.push('CUSTOMER SOURCE INCOMPLETE')}
  if(engineStrIncomplete(t)){if(severity==='normal'&&days!==null&&days<=14)severity='attention';score+=80;reasons.push('STR INCOMPLETE')}
  let openNc=(t.ncs||[]).filter(n=>n.state!=='Closed').length;if(openNc)score+=Math.min(100,openNc*15);
  let badgeCritical=brain.criticalBadges.filter(x=>!['noCustomer','noSalesOrder'].includes(x.key));let badgeAttention=brain.attentionBadges;
  if(badgeCritical.length){score+=Math.min(180,badgeCritical.length*18);reasons.push(`${badgeCritical.length} CRITICAL REQUIREMENT${badgeCritical.length===1?'':'S'}`)}
  if(badgeAttention.length){score+=Math.min(90,badgeAttention.length*12);reasons.push(`${badgeAttention.length} ATTENTION ITEM${badgeAttention.length===1?'':'S'}`)}
  if(t.toolStatus==='Shipped')score=-1000;
  return {tool:t,days,fiProgress:fiProgress(t),microProgress:microProgress(t),performance:perf[0],performanceCss:perf[2],shippingProgress:shippingProgress(t),severity,reasons,score,workload:t.toolStatus!=='Shipped'&&t.toolStatus!=='Archived',brain,badges:brain.badges,attentionCount:brain.attentionCount}
}
function commandCenterEngine(){
  let derived=operationalTools().map(deriveToolState),workload=derived.filter(x=>x.workload);
  let critical=workload.filter(x=>x.severity==='critical').sort((a,b)=>b.score-a.score);
  let attention=workload.filter(x=>x.severity==='attention').sort((a,b)=>b.score-a.score);
  let onTrack=workload.filter(x=>x.severity==='normal').sort((a,b)=>b.score-a.score);
  let priority=[...workload].sort((a,b)=>b.score-a.score||morningCompare(a.tool,b.tool));
  return {derived,workload,critical,attention,onTrack,priority,byId:new Map(derived.map(x=>[x.tool.id,x]))}
}
function morningCompare(a,b){let rank=t=>['Regera','Celestiq'].includes(t.codename)?(t.codename==='Regera'?1:2):0,ra=rank(a),rb=rank(b);if(ra!==rb)return ra-rb;return String(a.id||'').localeCompare(String(b.id||''),undefined,{numeric:true})}
function currentPriorityKind(){let d=new Date(today()+'T12:00:00').getDay();return(d===0||d===6)?'weekend':'weekday'}
function commandCenterPriorityList(){let eligible=new Set(priorityEligibleTools().map(t=>String(t.id)));return [...commandCenterEngine().derived].filter(x=>eligible.has(String(x.tool.id))).sort((a,b)=>b.score-a.score||morningCompare(a.tool,b.tool))}
function commandCenterPriorityRanks(){let m=new Map();commandCenterPriorityList().forEach((x,i)=>m.set(String(x.tool.id),i+1));return m}
function leadPriorityRanks(kind=currentPriorityKind()){
  let eligible=priorityEligibleTools(),eligibleIds=new Set(eligible.map(t=>String(t.id))),m=new Map(),seen=new Set(),rank=1,
      rows=[...(state.priorities?.[kind]||[])].filter(p=>eligibleIds.has(String(p.tool))).sort((a,b)=>(Number(a.priority)||9999)-(Number(b.priority)||9999));
  rows.forEach(p=>{if(!seen.has(String(p.tool))){seen.add(String(p.tool));m.set(String(p.tool),rank++)}});
  morningSortTools(eligible.filter(t=>!seen.has(String(t.id)))).forEach(t=>m.set(String(t.id),rank++));
  return m;
}
function priorityTier(rank,total){
  rank=Number(rank)||0;total=Math.max(0,Number(total)||0);
  if(!rank||!total)return 'PRIORITY';
  if(rank===1)return 'TOP PRIORITY';
  if(total<=2)return 'LOW PRIORITY';
  let pct=(rank-1)/Math.max(1,total-1);
  if(pct<=.30)return 'HIGH PRIORITY';
  if(pct>=.75)return 'LOW PRIORITY';
  return 'PRIORITY';
}
function priorityBadgeInfo(t){let source=state.config?.priorityBadgeSource||'lead',ranks=source==='commandCenter'?commandCenterPriorityRanks():leadPriorityRanks(),rank=ranks.get(String(t.id))||0,total=ranks.size;return{rank,total,tier:priorityTier(rank,total),source,label:source==='commandCenter'?'COMMAND CENTER':'LEADS / MANAGERS'}}
