function saveDirectIdentity(id,key){let i=state.tools.findIndex(x=>String(x.id)===String(id));if(i<0)return;let t=state.tools[i],v=String(document.querySelector('#direct-identity-value')?.value||'').trim(),map={utid:'id',toolType:'codename',model:'model',customer:'customer',salesOrder:'salesOrder'},prop=map[key];if(!prop)return;if(key==='utid'){if(!v)return alert('UTID / Serial is required.');let dup=state.tools.find((x,j)=>j!==i&&String(x.id).toLowerCase()===v.toLowerCase());if(dup)return alert(`DUPLICATE TOOL — ${v} already exists.`);let old=t.id;t.id=v;state.priorities&&Object.values(state.priorities).forEach(list=>(list||[]).forEach(p=>{if(String(p.tool)===String(old))p.tool=v}));if(Array.isArray(state.config?.dailyOrder))state.config.dailyOrder=state.config.dailyOrder.map(x=>String(x)===String(old)?v:x)}else{t[prop]=v==='N/A'?'':v;if(key==='customer')t.customerAvailability=v&&v!=='N/A'?'Available':'Not Available';if(key==='salesOrder')t.salesOrderAvailability=v&&v!=='N/A'?'Available':'Not Available'}state.tools[i]=normalizeTool(t);saveState(`${String(key).toUpperCase()} UPDATED`);closeModal();render();if(presentationActive)requestAnimationFrame(()=>requestAnimationFrame(fitPresentation))}
function carouselTools(){let a=operationalTools();let inPresentation=presentationActive||document.body.classList.contains('presentation-mode');if(!inPresentation)return a;let ranks=(state.config?.priorityBadgeSource||'lead')==='commandCenter'?commandCenterPriorityRanks():leadPriorityRanks();return [...a].sort((x,y)=>(ranks.get(String(x.id))||9999)-(ranks.get(String(y.id))||9999)||morningCompare(x,y))}

function requiresMST(t){return ['regera','celestiq'].includes(String(t.codename||'').toLowerCase())}
