function openIssueCount(){return state.actions.filter(a=>a.status!=='Complete').length+state.tools.reduce((n,t)=>n+t.ncs.filter(x=>x.state==='Escalated').length,0)}
function statusBars(){let e=commandCenterEngine(),lead=e.critical[0],sys=e.attention[0]||e.critical[0];let leadMsg=lead?`TOOL ${lead.tool.id} — ${(lead.reasons||[]).join(' — ')}`:'NO CRITICAL LEAD ALERTS';let sysMsg=sys?`TOOL ${sys.tool.id} — ${(sys.reasons||[]).join(' — ')}`:`${e.workload.length} ACTIVE WORKLOAD TOOLS — SYSTEM NORMAL`;let issueCount=openIssueCount();document.querySelector('#statusStack').innerHTML=`<div class="status-bar ${lead?'critical':'normal'}"><div class="status-left"><span class="status-dot"></span><div class="status-label"><strong>LEADS ALERT</strong><small>${lead?'CRITICAL':'NORMAL'}</small></div></div><div class="status-message ${lead?'clickable-status':''}" ${lead?`data-alert-tool="${esc(lead.tool.id)}" role="button" tabindex="0" title="Open tool ${esc(lead.tool.id)}"`:''}>${esc(leadMsg)}</div><button class="status-right status-open-button" data-open-issues type="button">← OPEN ${issueCount}</button></div><div class="status-bar ${sys?'attention':'normal'}"><div class="status-left"><span class="status-dot"></span><div class="status-label"><strong>SYSTEM STATUS</strong><small>${sys?'ATTENTION':'INFORMATION'}</small></div></div><div class="status-message ${sys?'clickable-status':''}" ${sys?`data-alert-tool="${esc(sys.tool.id)}" role="button" tabindex="0" title="Open tool ${esc(sys.tool.id)}"`:''}>${esc(sysMsg)}</div><button class="status-right status-open-button" data-open-issues type="button">← OPEN ${issueCount}</button></div>`}
function actionsFor(){let a=[];const shot=['SCREENSHOT','shot'];if(mode==='edit'){let saveLabel=(route.center==='operations'&&route.sub==='daily')?'SAVE UPDATES':'SAVE CHANGES';a.push(['CANCEL','cancel'],[saveLabel,'save','save']);if(route.center==='operations'&&route.sub==='tool'&&selected)a.push(['ARCHIVE TOOL','archiveTool','danger'],['DELETE TOOL','deleteTool','danger']);a.push(shot);return a}if(mode==='create'){a.push(['CANCEL','cancel'],[route.center==='operations'?'SAVE TOOL':'CREATE','save','save'],shot);return a}if(mode==='morningMeeting'){a.push(['CANCEL','cancel'],['SAVE MEETING','save','save'],['COMPLETE MEETING','completeMorning','primary'],shot);return a}if(mode==='meeting'){a.push(['CANCEL','cancel'],['SAVE MEETING','save','save'],['END MEETING','endMeeting','primary'],shot);return a}
 if(route.center==='operations'){if(route.sub==='live')a.push(['VERIFY TOOLS','verifyTools','primary']);if(route.sub==='live'||route.sub==='tools')a.push(['UPDATE COMMAND CENTER','updateAll','primary']);if(route.sub==='tools')a.push(['ADD TOOL','addTool','primary']);if(route.sub==='archive')a.push(['ADD TOOL TO ARCHIVE','archiveAdd','primary']);a.push(shot)}
 else if(route.center==='shipping'){a.push(['EDIT SHIPPING','edit','primary'],shot)}
 else if(route.center==='priority'){a.push(['EDIT PRIORITIES','edit','primary'],shot)}
 else if(route.center==='status'){if(route.sub==='weekday'||route.sub==='weekend'){let mt=route.sub==='weekend'?'Weekend Morning Meeting':'Weekday Morning Meeting';a.push(['UPDATE MORNING STATUS','edit','primary'],[findMorningDraft(mt)?'RESUME MORNING MEETING':'START MORNING MEETING','startMorning','primary'])}a.push(shot)}
 else if(route.center==='meeting'){a.push(['START MEETING','startMeeting','primary'],shot)}
 else if(route.center==='action'){a.push(['ADD ACTION','createAction','primary'],shot)}
 else if(route.center==='reference'){a.push(['ADD REFERENCE','createReference','primary'],shot)}

 else a.push(shot);return a}
function renderActions(){let host=document.querySelector('#pageActions');let normal=actionsFor().map(x=>{let core=x[1]==='addTool'?` onclick="event.stopPropagation();window.B7Core.addTool();return false"`:x[1]==='save'&&route.center==='operations'&&route.sub==='tool'?` onclick="event.stopPropagation();window.B7Core.saveTool();return false"`:x[1]==='cancel'&&route.center==='operations'&&route.sub==='tool'?` onclick="event.stopPropagation();window.B7Core.cancelTool();return false"`:'';return `<button data-act="${x[1]}" class="${x[2]||''}"${core}>${x[0]}</button>`}).join('');if(route.center==='operations'&&route.sub==='tools'&&mode==='view')normal=toolTypeMenu()+normal;if(route.center==='operations'&&route.sub==='live'&&mode==='view'){let n=nonArchivedTools().length||0;if(document.body.classList.contains('presentation-mode')){host.innerHTML='';return}host.innerHTML=`<div class="ops-action-controls"><div class="ops-control-group"><button class="ops-mini-btn" data-snapshot="prev">◀</button><span class="ops-count">${snapshotIndex+1} / 6</span><button class="ops-pause-btn" data-snapshot="pause"><b>STATUS</b><span>${snapshotPaused?'PLAY':'PAUSE'}</span></button><button class="ops-mini-btn" data-snapshot="next">▶</button></div><div class="ops-control-group"><button class="ops-mini-btn" data-carousel="prev" ${n?'':'disabled'}>◀</button><span class="ops-count">${n?liveIndex+1:0} / ${n}</span><button class="ops-pause-btn" data-carousel="${livePaused?'play':'pause'}" ${n?'':'disabled'}><b>TOOLS</b><span>${livePaused?'PLAY':'PAUSE'}</span></button><button class="ops-mini-btn" data-carousel="next" ${n?'':'disabled'}>▶</button></div></div><div class="ops-action-right">${normal}</div>`;return}host.innerHTML=normal}
function syncStickyShellHeight(){if(document.body.classList.contains('screenshot-mode')||document.body.classList.contains('presentation-mode')){document.documentElement.style.setProperty('--sticky-shell-height','0px');return}let sh=document.querySelector('#stickyShell');if(sh)document.documentElement.style.setProperty('--sticky-shell-height',Math.ceil(sh.getBoundingClientRect().height)+'px')}
function shell(){normalizeConsolidatedRoute();setTheme();document.body.dataset.build=BUILD;nav();statusBars();renderActions()}
function render(){allRules();shell();let titleMode=document.body.classList.contains('screenshot-mode')||document.body.classList.contains('presentation-mode');let title=titleMode?`<div id="screenshotReportTitle" class="screenshot-report-title">${esc(screenshotReportTitle())}</div>`:'';document.querySelector('#app').innerHTML=title+(VIEWS[route.center]||VIEWS.operations)();bindInputs();bindCoreInteractions();persistRoute();requestAnimationFrame(syncStickyShellHeight);if(document.body.classList.contains('presentation-mode'))requestAnimationFrame(()=>requestAnimationFrame(fitPresentation))}
function go(center,sub){if(dirty&&!confirm('Discard unsaved changes?'))return;mode='view';toolEditorMode='view';draft=null;meetingDraft=null;dirty=false;selected=null;returnRoute=null;let first=(SUB[center]&&SUB[center][0])?SUB[center][0][0]:'home';route={center,sub:sub||first};let app=document.querySelector('#app');if(app)app.innerHTML='';render()}
function fmtDate(x){if(!x)return'—';let p=String(x).slice(0,10).split('-');return p.length===3?`${p[1]}/${p[2]}/${p[0]}`:x}
function fmtDayDate(x){if(!x)return'—';let p=String(x).slice(0,10).split('-');if(p.length!==3)return x;let y=Number(p[0]),m=Number(p[1]),d=Number(p[2]),day=['SUNDAY','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'][new Date(y,m-1,d).getDay()];return `${day} · ${p[1]}/${p[2]}/${p[0]}`}
function centerPageTitle(label){if(document.body.classList.contains('screenshot-mode')||document.body.classList.contains('presentation-mode'))return'';return `<div class="report-title center-page-title">${esc(label)} · ${esc(fmtDate(today()))}</div>`}
function option(v,label,sel){return `<option value="${esc(v)}" ${v===sel?'selected':''}>${esc(label||v)}</option>`}
function selectOptions(arr,sel){return arr.map(x=>option(x,x,sel)).join('')}
const DRIVER_ROSTER=['Vinh','Hao','Daniel','Doan','Quoc','Joseph','Phillip','Tony N','Tony F','Hailey','Gonzalo','Neptune','Cymon','Nevin','Lihua','Allan','Jeryl','Gabin','Remfil','Ramil','Bryan','Kenny','Benson','Henry','Tuan','Truman','Randy','Stefan','Creed'];
function driverChoices(current=''){let vals=['Unassigned',...DRIVER_ROSTER,...state.tools.flatMap(t=>String(t.driver||'').split('/').map(x=>x.trim())).filter(x=>x&&!/^unassigned$/i.test(x))];if(current&&!vals.includes(current))vals.push(current);return [...new Set(vals)].sort((a,b)=>a==='Unassigned'?-1:b==='Unassigned'?1:a.localeCompare(b));}
function driverOptions(current=''){return selectOptions(driverChoices(current),current||'Unassigned')}
function routeOptions(t,sel){return routeFor(t).map(([c,n])=>option(c,`${c} — ${n}`,sel)).join('')}
function checklistLabel(t,code){if(!code)return'NOT SET';let r=routeFor(t).find(x=>x[0]===code);return r?`${r[0]} — ${r[1]}`:String(code)}
function fiWorkingRows(t,n=4){let st=ensureFiChecklistStates(t),route=routeFor(t),out=[];route.filter(([c])=>['In Progress','Open'].includes(st[c])).forEach(x=>out.push(x));let idx=Math.max(0,checklistIndex(t,t.currentChecklist));for(let i=idx;i<route.length&&out.length<n;i++){let x=route[i];if(st[x[0]]==='Not Started'&&!out.some(y=>y[0]===x[0]))out.push(x)}return out.slice(0,n)}
function shipDayDate(v){if(!v)return'';let d=new Date(v+'T12:00:00');if(Number.isNaN(d.getTime()))return fmtDate(v);return d.toLocaleDateString('en-US',{weekday:'long'}).toUpperCase()+' · '+fmtDate(v)}
function shipCountdown(t){
 let dd=shipDayDate(t.shipDate);
 if(t.toolStatus==='Shipped')return{big:'SHIPPED',small:dd,tone:'shipped'};
 if(!t.shipDate)return{big:'NO SHIP DATE',small:'SET MFG SHIP DATE',tone:'neutral'};
 let a=dateOnly(today()),b=dateOnly(t.shipDate),d=Math.round((b-a)/86400000),fi=fiProgress(t),pack=shippingProgress(t),tone='normal';
 if(d<0)return{big:`${Math.abs(d)} DAY${Math.abs(d)===1?'':'S'} OVERDUE`,small:dd,tone:'critical'};
 if(d===0){tone=(t.toolStatus==='Packing'&&pack>=90)?'warning':'critical';return{big:'SHIPS TODAY',small:dd,tone}}
 if(d===1){tone=(t.toolStatus==='Packing'&&pack>=75)?'warning':'critical';return{big:'SHIPS TOMORROW',small:dd,tone}}
 if(d<=5){
   if(['OPI','OI'].includes(t.toolStatus))tone='critical';
   else if(t.toolStatus==='FI')tone=fi>=90?'warning':'critical';
   else if(t.toolStatus==='Powered Down')tone='warning';
   else if(t.toolStatus==='Packing')tone=pack>=75?'ready':pack>=25?'warning':'critical';
   else tone='critical';
 }else if(d<=10){
   if(['OPI','OI'].includes(t.toolStatus))tone='critical';
   else if(t.toolStatus==='FI')tone=fi>=85?'ready':fi>=70?'warning':'critical';
   else if(['Powered Down','Packing'].includes(t.toolStatus))tone='ready';
   else tone='warning';
 }else if(d<=21){
   if(['OPI','OI'].includes(t.toolStatus))tone='warning';
   else if(t.toolStatus==='FI'&&fi<60)tone='warning';
   else if(['Powered Down','Packing'].includes(t.toolStatus))tone='ready';
 }
 return{big:`${d} DAYS TO SHIP`,small:dd,tone};
}
function nextFiMilestone(t){let r=routeFor(t),i=checklistIndex(t,t.currentChecklist);if(!r.length)return'NOT SET';if(i<0)return checklistLabel(t,r[0][0]);if(i>=r.length-1)return'FINAL FI CHECKLIST';return checklistLabel(t,r[i+1][0])}
function snapshotDisplay(html){return String(html).replace(/\sdata-tool="[^"]*"/g,'').replace(/\sdata-alert-tool="[^"]*"/g,'').replace(/\sdata-search-tool="[^"]*"/g,'')}
function toolTypeOptions(sel){let arr=FAMILIES.slice();if(sel&&!arr.includes(sel))arr.push(sel);return selectOptions(arr,sel)}
function modelOptions(t,sel){let arr=(PRODUCT_CATALOG[t.codename]||[]).slice();if(sel&&!arr.includes(sel))arr.unshift(sel);if(!arr.length)arr=['TBD'];return arr.map(x=>option(x,x,sel||arr[0])).join('')}
function quarterBounds(q){let m=String(q||'').match(/^CY(\d{2})Q([1-4])$/i);if(!m)return null;let y=2000+Number(m[1]),qn=Number(m[2]),sm=(qn-1)*3;return{start:new Date(y,sm,1,12),end:new Date(y,sm+3,0,12)}}
function quarterTimeProgress(){let b=quarterBounds(state.quarter);if(!b)return{pct:0,remainingPct:0,remaining:0,text:'QUARTER DATES NOT SET',tone:'normal'};let now=dateOnly(today()),total=Math.max(1,Math.round((b.end-b.start)/86400000)+1),elapsed=Math.min(total,Math.max(0,Math.round((now-b.start)/86400000)+1)),remaining=Math.max(0,Math.round((b.end-now)/86400000));let pct=Math.max(0,Math.min(100,Math.round(elapsed/total*100))),remainingPct=now>b.end?0:Math.max(0,Math.min(100,100-pct)),text=now>b.end?'QUARTER COMPLETE':remaining===0?'FINAL DAY':`${remaining} DAY${remaining===1?'':'S'} REMAINING`;return{pct,remainingPct,remaining,text,tone:remaining<=7?'critical':remaining<=21?'attention':'normal'}}
function fiSummaryStatus(t){if(['OPI','OI'].includes(t.toolStatus))return'Waiting';if(['FI','Powered Down'].includes(t.toolStatus))return'In FI';if(t.toolStatus==='Packing')return'Packing';if(t.toolStatus==='Shipped')return'Shipped';if(t.toolStatus==='Engineering')return'Engineering';return'Waiting'}
function quarterPanel(){
  let a=activeTools(),
      c=s=>a.filter(t=>fiSummaryStatus(t)===s).length,
      sh=c('Shipped'),
      pct=a.length?Math.round(sh/a.length*100):0,
      base=Number(state.config?.plannedCount)||0,
      pulled=state.tools.filter(t=>t.toolStatus!=='Archived'&&t.quarter===state.quarter&&t.originalQuarter&&t.originalQuarter!==state.quarter).length,
      pushed=state.tools.filter(t=>t.originalQuarter===state.quarter&&t.quarter!==state.quarter).length,
      updated=base>0?Math.max(0,base+pulled-pushed):0,
      qt=quarterTimeProgress();

  let box=(cls,label,val,active=true)=>`<div class="summary-box ${cls} ${active?'':'summary-disabled'}"><span>${label}</span><b>${active?val:0}</b></div>`;

  let mystery=familyNames().map(f=>{
    let fam=a.filter(t=>String(t.codename||'').toLowerCase()===f.toLowerCase()),
        shipped=fam.filter(t=>t.toolStatus==='Shipped').length,
        unlocked=fam.length>0&&shipped===fam.length;
    return `<button class="quarter-mystery-box ${unlocked?'unlocked':'locked'}" data-reveal="${esc(f)}" type="button" title="${unlocked?'Open celebration':'Ships all '+f+' tools to unlock'}">
      <b>${esc(f).toUpperCase()}</b>
      <small>${unlocked?'🎁 UNLOCKED':'🔒 '+shipped+'/'+fam.length+' SHIPPED'}</small>
    </button>`;
  }).join('');

  return `<section class="panel quarter-live-panel">
    <div class="summary-grid">
      ${box('summary-quarter',`${state.quarter} TOOLS`,a.length)}
      ${box('summary-pulled',`PULLED INTO ${state.quarter}`,pulled,pulled>0)}
      ${box('summary-pushed','PUSHED OUT',pushed,pushed>0)}
      ${box('summary-planned',`UPDATED ${state.quarter} TOOLS`,updated,base>0)}
      ${box('status-waiting','WAITING FI',c('Waiting'))}
      ${box('status-infi','IN FI',a.filter(t=>fiSummaryStatus(t)==='In FI').length)}
      ${box('status-packing','PACKING',c('Packing'))}
      ${box('status-shipped','SHIPPED',sh)}
    </div>
    <div class="shipping-total">
      <div class="progress-head"><b>${esc(state.quarter)} TOOLS SHIPPING PROGRESS</b><b>${sh} OF ${a.length} TOOLS SHIPPED</b></div>
      <div class="track"><div class="fill green" style="width:${pct}%"></div></div>
    </div>
    <div class="quarter-time-progress ${qt.tone}">
      <div class="progress-head"><b>${esc(state.quarter)} DAYS REMAINING</b><b>${esc(qt.text)}</b></div>
      <div class="track"><div class="fill quarter-days" style="width:${qt.remainingPct}%"></div></div>
    </div>
    <div class="quarter-mystery-strip">
      <div class="quarter-mystery-grid">${mystery||'<span class="muted">No active tool families.</span>'}</div>
    </div>
  </section>`;
}

