function familyNames(){let names=[];activeTools().forEach(t=>{let n=String(t.codename||'UNKNOWN').trim();if(n&&!names.some(x=>x.toLowerCase()===n.toLowerCase()))names.push(n)});return names.sort((a,b)=>a.localeCompare(b))}
