function cycleTimeView(){let a=operationalTools().filter(t=>['FI','Engineering','Powered Down','Packing'].includes(t.toolStatus)||t.fiHandoffDate);let groups={};a.forEach(t=>(groups[t.codename]??=[]).push(t));let rows=Object.entries(groups).sort().flatMap(([f,ts])=>ts.map(t=>{let actual=actualCycleDays(t),avg=cycleAverageDays(t),pct=avg?Math.round(actual/avg*100):0,[health,cls]=cycleHealth(t);return `<tr><td><b>${esc(t.id)}</b></td><td>${esc(f)}</td><td>${esc(fmtDate(t.fiHandoffDate)||'—')}</td><td>${actual?`DAY ${actual}`:'NOT STARTED'}</td><td>${avg?avg+' DAYS':'TBD'}</td><td><div class="track"><div class="fill ${pct>100?'red':pct>=85?'amber':'green'}" style="width:${Math.min(100,pct)}%"></div></div><small>${avg?pct+'%':'TARGET TBD'}</small></td><td class="cycle-health ${cls}">${esc(health)}</td><td>${esc(nextStepLabel(t))}${forecastNextDate(t)?`<small>FORECAST ${esc(fmtDate(forecastNextDate(t)))}</small>`:''}</td></tr>`}));return `<section class="panel cycle-time-frame"><table class="data-table cycle-time-table"><thead><tr><th>TOOL</th><th>TYPE</th><th>FI HANDOFF</th><th>CURRENT CYCLE</th><th>AVG CYCLE</th><th>CYCLE PROGRESS</th><th>STATUS</th><th>NEXT STEP / FORECAST</th></tr></thead><tbody>${rows.join('')||'<tr><td colspan="8">No tools currently accumulating FI cycle time.</td></tr>'}</tbody></table></section>`}
