  if(remaining<=5)return {label:'LAMP',state:`SWAP LAMP · ${hours} HRS`,active:true,tone:'critical',hours,limit,remaining};
  if(remaining<=50)return {label:'LAMP',state:`SWAP LAMP SOON · ${hours} HRS`,active:true,tone:'attention',hours,limit,remaining};
