document.addEventListener('click',e=>{
  const toggle=e.target.closest('[data-tool-type-toggle]');
  if(toggle){
    e.preventDefault();e.stopPropagation();
    const menu=toggle.closest('[data-tool-type-menu]');
    const open=!menu.classList.contains('open');
    document.querySelectorAll('[data-tool-type-menu].open').forEach(x=>{x.classList.remove('open');x.querySelector('[data-tool-type-toggle]')?.setAttribute('aria-expanded','false')});
    if(open){positionToolTypeMenu(menu);menu.classList.add('open');toggle.setAttribute('aria-expanded','true')}
    return;
  }
  const item=e.target.closest('[data-tool-type-target]');
  if(item){
    e.preventDefault();e.stopPropagation();
    const target=document.getElementById(item.dataset.toolTypeTarget);
    item.closest('[data-tool-type-menu]')?.classList.remove('open');
    item.closest('[data-tool-type-menu]')?.querySelector('[data-tool-type-toggle]')?.setAttribute('aria-expanded','false');
    if(target){let shellH=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--sticky-shell-height'))||0,y=target.getBoundingClientRect().top+window.scrollY-shellH-8;window.scrollTo({top:Math.max(0,y),behavior:'smooth'})};
    return;
  }
  if(!e.target.closest('[data-tool-type-menu]'))document.querySelectorAll('[data-tool-type-menu].open').forEach(x=>{x.classList.remove('open');x.querySelector('[data-tool-type-toggle]')?.setAttribute('aria-expanded','false')});
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('[data-tool-type-menu].open').forEach(x=>{x.classList.remove('open');x.querySelector('[data-tool-type-toggle]')?.setAttribute('aria-expanded','false')})});
document.addEventListener('pointerover',e=>{let menu=e.target.closest?.('[data-tool-type-menu]');if(menu)positionToolTypeMenu(menu)});

