/* V6.1.4 checklist collapse controls */
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-collapse-target]');
  if(!b)return;
  const el=document.getElementById(b.dataset.collapseTarget);
  if(!el)return;
  const collapsed=el.classList.toggle('collapsed');
  b.textContent=collapsed?'EXPAND':'MINIMIZE';
});
